import{_ as s}from"./chunks/logo-full.BTf1ACha.js";import{_ as t,o as i,c as e,a0 as n}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"关于我们 | 爆雪科技","description":"了解爆雪科技，科技引爆增长，数据重塑品牌。","frontmatter":{"layout":"page","title":"关于我们 | 爆雪科技","description":"了解爆雪科技，科技引爆增长，数据重塑品牌。"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),o={name:"about/index.md"};function c(p,a,l,d,r,_){return i(),e("div",null,[...a[0]||(a[0]=[n('<main class="bx-site"><section class="section section--white" aria-labelledby="about-title"><div class="section__inner two-column"><div><p class="section-label">关于我们</p><h2 id="about-title">科技引爆增长，数据重塑品牌</h2></div><div class="copy-block"><p>杭州爆雪科技有限公司（简称“爆雪科技”）成立于2021年，总部位于中国数字经济第一城——杭州。作为专注于AR增强现实与AI人工智能商业化落地的技术企业，我们深耕饮品、汽车及高端零售行业，致力于成为品牌方最信赖的“数智化营销合伙人”。</p><p>我们独创“线下沉浸体验 + 线上实景直播”双轮驱动模式。区别于传统的硬件厂商或单一软件外包公司，爆雪科技更懂内容、懂营销。我们通过自研的核心算法与系统，帮助品牌打破物理空间限制，将线下流量高效转化为线上销量，实现“体验即营销”的数字化闭环。</p></div></div></section><section class="section section--ink" aria-labelledby="tech-title"><div class="section__inner"><div class="section-heading section-heading--center"><p class="section-label">技术实力 · 核心专利壁垒</p><h2 id="tech-title">掌握底层核心技术，构筑行业护城河</h2><p>爆雪科技拥有一支来自BAT背景的技术团队，研发投入占比超过40%。我们拥有完全自主知识产权的空间感知引擎与实时渲染管线，已获得多项发明专利与软件著作权，构建了坚实的技术壁垒。</p></div><div class="tech-grid" aria-label="核心自研技术"><article><span class="tech-index">01</span><h3>X-Space 空间锚定引擎</h3><p>告别传统SLAM的不稳定性，采用“图像+平面”双重锚定技术，实现厘米级精度的空间定位，确保虚拟内容与真实场景严丝合缝，永不穿模。</p></article><article><span class="tech-index">02</span><h3>Live-AR 实时合成系统</h3><p>基于NDI/OBS协议深度开发的直播推流内核。支持4K@60fps超高清画质输出，毫秒级延迟，完美适配抖音、视频号等主流直播平台。</p></article><article><span class="tech-index">03</span><h3>Digital Human 数字人驱动平台</h3><p>集成语音识别（ASR）、自然语言处理（NLP）与动作捕捉技术，让虚拟IP不仅能看，更能听懂观众指令，实现智能交互。</p></article></div><div class="credential-row" aria-label="知识产权与资质"><div><strong>发明专利</strong><span>《一种基于图像识别的AR直播方法及系统》</span><span>《一种轻量化3D模型在移动端的渲染优化方法》</span></div><div><strong>软件著作权</strong><span>爆雪AR内容创作平台</span><span>爆雪AR实景直播控制台</span><span>空间点云数据处理系统</span></div><div><strong>行业认证</strong><span>国家高新技术企业</span><span>ISO9001质量管理体系认证</span><span>ISO27001信息安全管理体系认证</span></div></div></div></section><footer class="footer" id="contact"><div class="footer__inner"><div class="footer__brand"><img class="footer-logo" src="'+s+'" alt="爆雪科技"><div><strong>杭州爆雪科技有限公司</strong><p>AR+AI 数智化营销全栈服务商</p></div></div><div class="footer__contact"><h2>联系我们</h2><p>公司地址：浙江省杭州市 [具体区] [具体地址]</p><p>联系电话：0571-XXXX XXXX</p><p>商务合作：<a href="mailto:bd@baoxue-tech.com">bd@baoxue-tech.com</a></p><p>官方微信/公众号：杭州爆雪科技</p></div><div class="footer__copyright"><p>© 2026 杭州爆雪科技有限公司</p></div></div></footer></main>',1)])])}const m=t(o,[["render",c]]);export{b as __pageData,m as default};
